import torch

def run(x, from_val, to_val):
    x.uniform_(from_val, to_val)
    return x

def valid(ref_outputs, sol_outputs, inputs, ctx):
    out = sol_outputs[0]
    from_val = ctx['from_val']
    to_val = ctx['to_val']
    within_range = bool((out >= from_val).all() and (out <= to_val).all())
    return {'passed': within_range, 'message': f'All values in [{from_val}, {to_val}]: {within_range}', 'metrics': {}}
